package mz.bam.seeky.android;
import android.content.*;import java.util.*;import org.json.*;
final class MetadataWork {
    static void run(Context c,StudyStore.Row job,TaskStore work,TaskService.Control control)throws Exception{JSONObject data=new JSONObject(job.s("payload"));String id=job.s("id");try(StudyStore books=new StudyStore(c);PlusStore plus=new PlusStore(c)){while(true){control.check();List<StudyStore.Row> rows=work.items(id,"pending",0,1);if(rows.isEmpty())break;StudyStore.Row item=rows.get(0);String hash=PlusStore.hash(item.s("uri"));ContentValues edits=new ContentValues();if(data.optBoolean("author_set"))edits.put("author",data.optString("author"));if(!data.optString("prefix").isEmpty())edits.put("title",AudioTitles.limit(data.getString("prefix")+" "+item.s("name"),240,720));edits.put("updated",System.currentTimeMillis());books.getWritableDatabase().update("materials",edits,"hash=?",new String[]{hash});plus.getWritableDatabase().execSQL("INSERT OR IGNORE INTO book_meta(hash) VALUES(?)",new Object[]{hash});ContentValues meta=new ContentValues();if(data.optBoolean("series_set"))meta.put("series",data.optString("series"));if(data.optBoolean("topic_set"))meta.put("topic",data.optString("topic"));if(meta.size()>0)plus.getWritableDatabase().update("book_meta",meta,"hash=?",new String[]{hash});BookSettings.update(c,hash,profile->{if(data.optBoolean("author_set"))profile.put("manual_author",true);if(!data.optString("prefix").isEmpty())profile.put("manual_title",true);});work.item(id,(int)item.n("seq"),StudyStore.values("state","done","message","Actualizado"));long total=work.count(id,null),done=work.count(id,"done");control.progress(done+" / "+total+" livros actualizados",done,total);}}StudyEvents.changed();}
    private MetadataWork(){}
}
